/**
 * @file `astryx upgrade` end to end: generated files to rebuild are listed in
 * `regenerate` with their commands. A file the project protects keeps the run
 * incomplete (ERR_CODEMOD_PROTECTED, as for any protected file); one nothing
 * protects stays a codemod error (ERR_CODEMOD_FAILED). A declared
 * regeneration clears them, and a real codemod failure keeps its
 * ERR_CODEMOD_FAILED error.
 * Manual migrations are covered at the API level in
 * `api/upgrade/run/outcomes.test.mjs`.
 */

import {afterEach, beforeEach, describe, expect, it} from 'vitest';
import {spawnSync} from 'node:child_process';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import {fileURLToPath} from 'node:url';
import {CLI_VERSION} from '../../../test-utils/release-fixtures.mjs';

const CLI = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '..',
  'bin',
  'astryx.mjs',
);
const CODEMOD = 'core:validate-data-token-ownership';
const STALE_THEME =
  '/* @generated by `astryx theme build` */\n' +
  '@layer astryx-base {\n  :root { --color-data-categorical-green: #008000; }\n}\n';
const FRESH_THEME = '/* @generated by `astryx theme build` */\n.theme {}\n';
// The generated block below authored rules: the marker is not in the leading
// comment block, so nothing protects this file (spec:AST-040 FR3).
const UNPROTECTED_STALE_THEME = `.app { color: red; }\n${STALE_THEME}`;

let root;

function write(relative, contents) {
  const file = path.join(root, relative);
  fs.mkdirSync(path.dirname(file), {recursive: true});
  fs.writeFileSync(file, contents);
}

function read(relative) {
  return fs.readFileSync(path.join(root, relative), 'utf8');
}

function run(args, {json = true, cwd = root} = {}) {
  const result = spawnSync(
    process.execPath,
    [CLI, ...(json ? ['--json'] : []), 'upgrade', ...args],
    {
      cwd,
      encoding: 'utf8',
      timeout: 60_000,
      env: {...process.env, FORCE_COLOR: '0', CI: ''},
    },
  );
  return {...result, envelope: json ? JSON.parse(result.stdout) : null};
}

/** @param {{config?: string}} [options] */
function seed({config = 'export default {};\n'} = {}) {
  write(
    'package.json',
    JSON.stringify({
      name: 'consumer',
      private: true,
      dependencies: {'@astryxdesign/core': CLI_VERSION},
    }),
  );
  write(
    'node_modules/@astryxdesign/core/package.json',
    JSON.stringify({name: '@astryxdesign/core', version: CLI_VERSION}),
  );
  write('astryx.config.mjs', config);
}

const ONLY = ['--from', '0.6.0', '--codemod', 'validate-data-token-ownership'];

beforeEach(() => {
  root = fs.mkdtempSync(path.join(os.tmpdir(), 'astryx-upgrade-outcomes-'));
});

afterEach(() => {
  fs.rmSync(root, {recursive: true, force: true});
});

describe('generated files to regenerate', () => {
  it('are listed with the rebuild command, and in protectedFiles with the declaration that protects them', () => {
    seed();
    write('app/theme.css', STALE_THEME);

    const applied = run([...ONLY, '--path', '.', '--apply']);

    expect(applied.status).toBe(1);
    expect(applied.envelope).toMatchObject({
      type: 'upgrade.run',
      data: {
        complete: false,
        errorCode: 'ERR_CODEMOD_PROTECTED',
        errors: [],
        declinedCandidates: [],
        // The stale theme carries an @generated header, so it is a protected
        // file that still requires a change, with its declaration.
        protectedFiles: [
          {
            file: 'app/theme.css',
            codemods: [CODEMOD],
            reasons: ['generated'],
            declarations: [expect.stringContaining('@generated')],
            commands: ['astryx theme build'],
          },
        ],
        regenerate: [
          {
            file: 'app/theme.css',
            codemods: [CODEMOD],
            commands: ['astryx theme build'],
            messages: [expect.stringContaining('Rebuild it')],
          },
        ],
      },
    });
    expect(read('app/theme.css')).toBe(STALE_THEME);
  });

  it('read as incomplete in text, never as up to date', () => {
    seed();
    write('app/theme.css', STALE_THEME);

    const text = run([...ONLY, '--path', '.', '--apply'], {json: false});

    expect(text.status).toBe(1);
    expect(text.stderr).toMatch(
      /ERR_CODEMOD_PROTECTED: 1 protected file still requires a codemod change:\n\s+app\/theme\.css — .*@generated/,
    );
    expect(text.stdout).toMatch(/Regenerate with: astryx theme build/);
    expect(text.stdout).toMatch(/Upgrade incomplete/);
    expect(`${text.stdout}\n${text.stderr}`).not.toMatch(/No changes needed/);
  });

  it('keep the incomplete result, not a config error, when astryx.config fails validation too', () => {
    seed({config: "export default {theme: 'neutral'};\n"});
    write('app/theme.css', STALE_THEME);

    const applied = run([...ONLY, '--path', '.', '--apply']);

    expect(applied.status).toBe(1);
    expect(applied.envelope).toMatchObject({
      type: 'upgrade.run',
      data: {
        complete: false,
        errorCode: 'ERR_CODEMOD_PROTECTED',
        protectedFiles: [expect.objectContaining({file: 'app/theme.css'})],
        regenerate: [
          expect.objectContaining({
            file: 'app/theme.css',
            commands: ['astryx theme build'],
          }),
        ],
        // The config's own error is still listed, as main reports it.
        errors: [
          {
            file: '.',
            codemod: 'config',
            error: expect.stringContaining('astryx.config'),
          },
        ],
      },
    });

    const configError = applied.envelope.data.errors[0].error;
    const text = run([...ONLY, '--path', '.', '--apply'], {json: false});
    expect(text.status).toBe(1);
    expect(text.stderr).toContain(configError);
    expect(text.stdout).toMatch(/Upgrade incomplete: protected changes remain/);
  });

  it('include protected generated files with their header command, alongside protectedFiles', () => {
    seed();
    write('.gitattributes', 'generated/** linguist-generated=true\n');
    write(
      'generated/panel.tsx',
      '// @generated\n// Command: pnpm run gen:panel\n' +
        "import {useResizable} from '@astryxdesign/core';\n" +
        'export const usePanel = () => useResizable({minSizePx: 200});\n',
    );

    const applied = run([
      '--from',
      '0.5.0',
      '--codemod',
      'rename-resizable-pixel-bounds',
      '--path',
      '.',
      '--apply',
    ]);

    expect(applied.status).toBe(1);
    expect(applied.envelope.data).toMatchObject({
      complete: false,
      errorCode: 'ERR_CODEMOD_PROTECTED',
      protectedFiles: [expect.objectContaining({file: 'generated/panel.tsx'})],
      regenerate: [
        {
          file: 'generated/panel.tsx',
          codemods: ['core:rename-resizable-pixel-bounds'],
          commands: ['pnpm run gen:panel'],
          messages: [],
        },
      ],
    });
  });

  it('clear once the declared regeneration rebuilds the file', () => {
    const rebuild = `require('node:fs').writeFileSync('app/theme.css', ${JSON.stringify(FRESH_THEME)})`;
    seed({
      config: `export default {hooks: {postCodemod: [{name: 'theme', buildCommand: () => ({command: process.execPath, args: ['-e', ${JSON.stringify(rebuild)}]})}]}};\n`,
    });
    write('app/theme.css', STALE_THEME);

    const applied = run([...ONLY, '--path', '.', '--apply']);

    expect(applied.status, applied.stderr).toBe(0);
    expect(applied.envelope.data).toMatchObject({
      complete: true,
      regenerate: [],
      modifiedFiles: ['app/theme.css'],
    });
    expect(read('app/theme.css')).toBe(FRESH_THEME);
  });

  it('report one nothing protects as a codemod error, not ERR_CODEMOD_PROTECTED', () => {
    seed();
    write('app/theme.css', UNPROTECTED_STALE_THEME);

    const applied = run([...ONLY, '--path', '.', '--apply']);

    expect(applied.status).toBe(1);
    expect(applied.envelope).not.toHaveProperty('type');
    expect(applied.envelope).toMatchObject({
      code: 'ERR_CODEMOD_FAILED',
      receipt: {
        complete: false,
        errorCode: 'ERR_CODEMOD_FAILED',
        protectedFiles: [],
        errors: [
          expect.objectContaining({
            file: 'app/theme.css',
            codemod: CODEMOD,
            error: expect.stringContaining('Rebuild it'),
          }),
        ],
        regenerate: [
          expect.objectContaining({
            file: 'app/theme.css',
            commands: ['astryx theme build'],
          }),
        ],
      },
    });

    const text = run([...ONLY, '--path', '.', '--apply'], {json: false});
    expect(text.status).toBe(1);
    expect(text.stderr).toMatch(
      /1 generated file must be regenerated:\n\s+app\/theme\.css — /,
    );
    expect(text.stderr).not.toMatch(/ERR_CODEMOD_PROTECTED/);
    expect(text.stdout).toMatch(/Regenerate with: astryx theme build/);
    expect(text.stdout).toMatch(/Upgrade failed/);
    expect(`${text.stdout}\n${text.stderr}`).not.toMatch(
      /No changes needed|Done!/,
    );
  });

  it('name files from the folder the command runs in', () => {
    seed();
    write('app/theme.css', STALE_THEME);

    const applied = run([...ONLY, '--path', '.', '--apply'], {
      cwd: path.join(root, 'app'),
    });

    expect(applied.envelope.data).toMatchObject({
      regenerate: [expect.objectContaining({file: 'theme.css'})],
    });
  });
});

describe('a real failure beside them', () => {
  function seedFailing() {
    seed({config: "export default {integrations: ['@acme/widgets']};\n"});
    write(
      'node_modules/@acme/widgets/package.json',
      JSON.stringify({name: '@acme/widgets', version: '1.0.0'}),
    );
    write(
      'node_modules/@acme/widgets/astryx.integration.mjs',
      "export default {codemods: './codemods'};\n",
    );
    write(
      'node_modules/@acme/widgets/codemods/0.7.0/fail.mjs',
      "export default {type: 'code', title: 'Fail on boom', transform: file => { if (file.source.includes('boom')) throw new Error('codemod boom'); return undefined; }};\n",
    );
    write('src/broken.ts', 'export const boom = 1;\n');
  }

  it('keeps the ERR_CODEMOD_FAILED error, whose receipt carries both lists', () => {
    seedFailing();

    const applied = run(['--from', '0.6.0', '--path', 'src', '--apply']);

    expect(applied.status).toBe(1);
    expect(applied.envelope).toMatchObject({
      code: 'ERR_CODEMOD_FAILED',
      receipt: {
        complete: false,
        errorCode: 'ERR_CODEMOD_FAILED',
        errors: [
          expect.objectContaining({
            file: 'src/broken.ts',
            codemod: '@acme/widgets:fail',
          }),
        ],
        declinedCandidates: [],
        regenerate: [],
      },
    });
  });

  it('with a protected file to regenerate, returns the incomplete receipt as for a protected file', () => {
    seedFailing();
    write('src/theme.css', STALE_THEME);

    const applied = run(['--from', '0.6.0', '--path', 'src', '--apply']);

    expect(applied.status).toBe(1);
    expect(applied.envelope).toMatchObject({
      type: 'upgrade.run',
      data: {
        complete: false,
        errorCode: 'ERR_CODEMOD_PROTECTED',
        errors: [expect.objectContaining({file: 'src/broken.ts'})],
        regenerate: [expect.objectContaining({file: 'src/theme.css'})],
      },
    });
  });
});
